// effectively final - snapshot w petli:
for (int i = 0; i < 3; i++) {
    final int snapshot = i;
    Runnable r = () -> System.out.println(snapshot);
    r.run();
}

// this w lambdzie vs klasie anonimowej:
class Greeter {
    String name;
    Runnable asLambda() {
        return () -> System.out.println(this.name); // this = Greeter
    }
    Runnable asAnonymousClass() {
        return new Runnable() {
            public void run() {
                System.out.println(Greeter.this.name); // this = anonimowa klasa!
            }
        };
    }
}
